// 并发限制器类
class ConcurrencyLimiter {
  private maxConcurrency: number;          // 最大并发数
  private runningCount: number = 0;         // 当前正在运行的任务数
  private queue: Array<{                   // 等待队列，存放待执行的任务及解析器
    task: () => Promise<any>;
    resolve: (value: any) => void;
    reject: (reason?: any) => void;
  }> = [];

  constructor(maxConcurrency: number) {
    if (maxConcurrency < 1) {
      throw new Error('最大并发数必须 >= 1');
    }
    this.maxConcurrency = maxConcurrency;
  }

  // 添加一个任务，返回该任务结果的 Promise
  add<T>(task: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      // 将任务及其回调打包存入队列
      this.queue.push({ task, resolve, reject });
      // 尝试执行下一个任务
      this.runNext();
    });
  }

  // 处理下一个任务（私有方法）
  private runNext(): void {
    // 如果正在运行的任务数达到上限，或者队列为空，则不做操作
    if (this.runningCount >= this.maxConcurrency || this.queue.length === 0) {
      return;
    }

    // 从队列头部取出一个任务并执行
    const item = this.queue.shift()!;
    this.runningCount++;

    // 执行任务，并确保完成时处理后续
    item.task()
      .then((result) => {
        item.resolve(result);           // 将成功结果传给外部调用者
      })
      .catch((error) => {
        item.reject(error);             // 将失败原因传给外部调用者
      })
      .finally(() => {
        this.runningCount--;            // 任务结束，减少运行计数
        this.runNext();                 // 从队列拉取下个任务
      });
  }
}

// 使用示例：模拟异步请求
// 创建一个最大并发为 2 的限制器
const limiter = new ConcurrencyLimiter(2);

// 模拟异步任务：延迟一段时间后返回
const delay = (ms: number, value: string): Promise<string> =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

// 依次添加 4 个任务
limiter.add(() => delay(1000, 'Task 1')).then(console.log);
limiter.add(() => delay(500,  'Task 2')).then(console.log);
limiter.add(() => delay(800,  'Task 3')).then(console.log);
limiter.add(() => delay(300,  'Task 4')).then(console.log);

// 预期行为：
// 同时启动 Task 1 和 Task 2（并发=2）。
// 500ms 后 Task 2 完成，释放一个槽位，启动 Task 3。
// 800ms 后 Task 3 完成（此时 Task 1 仍在运行），启动 Task 4。
// 1000ms 后 Task 1 完成。
// 1300ms 后 Task 4 完成。
// 最终输出顺序：Task 2, Task 3, Task 1, Task 4

